files.rule:
# The conversion policy both games declare: PROPORTIONAL. Damage, healing and a
# creature's health keep their share of a player's health: 7 of Blockcraft's 20
# HP is 35%, and 35% of a creature's 100 HP is 35. The elemental type passes
# through to a game that has types. This is a policy, not a fact. A game that
# wants absolute damage writes another rule. Lean does not check this file; it
# ships in every passport so that anyone can run it again.
#
# EVERY arithmetic chain below is fully parenthesised, and that is load-bearing.
# Oxigraph's SPARQL parser (spargebra 0.5, upstream and in the engine's fork)
# groups chains to the RIGHT: it reads 7/20*100 as 7/(20*100) = 0.0035 and
# 8-3-2 as 8-(3-2) = 7. The SPARQL 1.1 grammar makes both left-associative.
# tests/test_verdicts.py pins the numbers so the bug cannot come back silently.
#
# It reads the customs declaration `?item ga:importTarget ?target` that the
# receiving game asserts, so one rule serves both directions.

PREFIX ga: <https://tesseractsemantics.com/ns/asset-passport/ga#>

CONSTRUCT {
  ?item ga:damageInTarget    ?dmg ;
        ga:healInTarget      ?heal ;
        ga:hitPointsInTarget ?hp ;
        ga:typeInTarget      ?type .
}
WHERE {
  ?item ga:importTarget ?tgt ;
        ga:fromGame     ?src .
  ?src ga:maxPlayerHealth ?srcHp .
  ?tgt ga:maxPlayerHealth ?tgtHp .
  OPTIONAL { ?tgt ga:wholeNumbersOnly ?w }
  BIND (COALESCE(?w, false) AS ?whole)

  OPTIONAL { ?item ga:baseDamage ?d }
  BIND (((?d / ?srcHp) * ?tgtHp) AS ?dRaw)
  BIND (IF(?whole, ROUND(?dRaw), ?dRaw) AS ?dmg)

  OPTIONAL { ?item ga:healAmount ?h }
  BIND (((?h / ?srcHp) * ?tgtHp) AS ?hRaw)
  BIND (IF(?whole, ROUND(?hRaw), ?hRaw) AS ?heal)

  OPTIONAL { ?item ga:hitPoints ?p }
  BIND (((?p / ?srcHp) * ?tgtHp) AS ?pRaw)
  BIND (IF(?whole, ROUND(?pRaw), ?pRaw) AS ?hp)

  # A type crosses only into a game that declares it has types.
  OPTIONAL { ?tgt ga:hasElementalTypes true . ?item ga:elementalType ?type }
}

files.craft_border:
@prefix ga:  <https://tesseractsemantics.com/ns/asset-passport/ga#> .
@prefix sh:  <http://www.w3.org/ns/shacl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix c: <https://tesseractsemantics.com/ns/asset-passport/contract/craft#> .

# Blockcraft's border. Every shape is a refusal, in Blockcraft's units: hit
# points out of 20.

c:Provenance a sh:NodeShape ; sh:targetClass ga:Item ;
    sh:property [ sh:path ga:fromGame ; sh:minCount 1 ;
        sh:message "Blockcraft admits nothing that does not say which game its numbers are written in." ] .

c:NoCaptureDevices a sh:NodeShape ; sh:targetClass ga:Item ;
    sh:property [ sh:path rdf:type ; sh:not [ sh:hasValue ga:CaptureDevice ] ;
        sh:message "Blockcraft refuses capture devices. Nothing in Blockcraft can own a mob." ] .

c:NoOneHitKills a sh:NodeShape ; sh:targetSubjectsOf ga:baseDamage ;
    sh:property [ sh:path ga:damageInTarget ; sh:minCount 1 ; sh:maxExclusive 20 ;
        sh:message "Blockcraft refuses anything that would kill a full-health player (20 HP) in one hit." ] .

c:HealCap a sh:NodeShape ; sh:targetClass ga:HealingConsumable ;
    sh:property [ sh:path ga:healInTarget ; sh:minCount 1 ; sh:maxInclusive 20 ;
        sh:message "Blockcraft refuses a heal above a full 20 HP." ] .

c:PetSize a sh:NodeShape ; sh:targetClass ga:Creature ;
    sh:property [ sh:path ga:hitPointsInTarget ; sh:minCount 1 ; sh:maxInclusive 20 ;
        sh:message "A pet in Blockcraft has at most a player's 20 HP." ] .

files.battle_border:
@prefix ga:  <https://tesseractsemantics.com/ns/asset-passport/ga#> .
@prefix sh:  <http://www.w3.org/ns/shacl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix c: <https://tesseractsemantics.com/ns/asset-passport/contract/battle#> .

# Pocket Battlers' border. Every shape here is a REFUSAL, read on values the
# declared conversion produced, in Pocket Battlers' own units. Severity stays
# at its default on purpose: the verified evaluator ignores sh:severity, so
# warnings live in battle-loss.shacl.ttl.

c:Provenance a sh:NodeShape ; sh:targetClass ga:Item ;
    sh:property [ sh:path ga:fromGame ; sh:minCount 1 ;
        sh:message "Pocket Battlers admits nothing that does not say which game its numbers are written in." ] .

c:NoOneTurnKnockouts a sh:NodeShape ; sh:targetSubjectsOf ga:baseDamage ;
    sh:property [ sh:path ga:damageInTarget ; sh:minCount 1 ; sh:maxExclusive 100 ;
        sh:message "Pocket Battlers refuses anything that would knock out a full-health creature (100 HP) in one turn." ] .

c:MovesHaveAType a sh:NodeShape ; sh:targetClass ga:Weapon ;
    sh:property [ sh:path ga:typeInTarget ; sh:minCount 1 ;
        sh:message "Every move in Pocket Battlers has a type, and nothing places this weapon's material on the type scale." ] .

c:HealCap a sh:NodeShape ; sh:targetClass ga:HealingConsumable ;
    sh:property [ sh:path ga:healInTarget ; sh:minCount 1 ; sh:maxInclusive 100 ;
        sh:message "Pocket Battlers refuses a heal above a creature's full 100 HP." ] .

files.craft_loss:
@prefix ga:  <https://tesseractsemantics.com/ns/asset-passport/ga#> .
@prefix sh:  <http://www.w3.org/ns/shacl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix c: <https://tesseractsemantics.com/ns/asset-passport/contract/craft#> .

# What a thing loses on the way into Blockcraft.

c:NoTypes a sh:NodeShape ; sh:targetClass ga:Item ;
    sh:property [ sh:path ga:elementalType ; sh:maxCount 0 ; sh:severity sh:Warning ;
        sh:message "Blockcraft has no elemental types, so this thing's type advantages are dropped." ] .

files.battle_loss:
@prefix ga:  <https://tesseractsemantics.com/ns/asset-passport/ga#> .
@prefix sh:  <http://www.w3.org/ns/shacl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix c: <https://tesseractsemantics.com/ns/asset-passport/contract/battle#> .

# What a thing loses on the way into Pocket Battlers. Warnings: it still enters,
# and its passport names what had nowhere to go.

c:NoBonusHealth a sh:NodeShape ; sh:targetClass ga:Item ;
    sh:property [ sh:path ga:bonusHealth ; sh:maxCount 0 ; sh:severity sh:Warning ;
        sh:message "Pocket Battlers has no health above the maximum, so the extra hearts are dropped." ] .
